<?php
namespace Tests\Feature\Admin;use App\Livewire\Admin\Access\Groups;use App\Livewire\Admin\Users\Create;use App\Livewire\Admin\Users\Edit;use App\Models\Permission;use App\Models\PermissionGroup;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Livewire\Livewire;use Tests\TestCase;
class AccessControlWorkspaceTest extends TestCase{use RefreshDatabase;
public function test_group_permissions_are_effective_at_runtime():void{$permission=Permission::create(['name'=>'customers.view','display_name'=>'View customers','resource'=>'customers','action'=>'view']);$group=PermissionGroup::create(['name'=>'customer_readers','display_name'=>'Customer readers']);$group->permissions()->attach($permission);$user=User::factory()->create(['role'=>'marketing']);$user->permissionGroups()->attach($group,['granted_by'=>$user->id,'granted_at'=>now()]);$this->assertTrue($user->hasPermission('customers.view'));$this->assertTrue($user->hasAnyPermission(['customers.view']));$this->assertTrue($user->hasAllPermissions(['customers.view']));}
public function test_admin_creates_user_with_group_and_direct_permission():void{$admin=User::factory()->create(['role'=>'admin']);$group=PermissionGroup::create(['name'=>'sales_tools','display_name'=>'Sales tools']);$permission=Permission::create(['name'=>'quotes.view','display_name'=>'View quotes','resource'=>'quotes','action'=>'view']);$this->actingAs($admin);Livewire::test(Create::class)->set('name','New Sales User')->set('email','new-sales@example.test')->set('role','sales')->set('password','strong-password')->set('group_ids',[$group->id])->set('permission_ids',[$permission->id])->call('save')->assertHasNoErrors();$user=User::where('email','new-sales@example.test')->firstOrFail();$this->assertTrue($user->permissionGroups()->whereKey($group->id)->exists());$this->assertTrue($user->permissions()->whereKey($permission->id)->exists());}
public function test_hr_cannot_assign_admin_role_or_edit_admin_and_users_cannot_edit_self():void{$hr=User::factory()->create(['role'=>'hr']);$admin=User::factory()->create(['role'=>'admin']);$employee=User::factory()->create(['role'=>'sales']);$this->actingAs($hr);Livewire::test(Create::class)->set('name','Unsafe')->set('email','unsafe@example.test')->set('role','admin')->set('password','strong-password')->call('save')->assertHasErrors('role');$this->get(route('admin.users.edit',$admin))->assertForbidden();$this->actingAs($employee)->get(route('admin.users.edit',$employee))->assertForbidden();}
public function test_admin_manages_permission_group_catalog():void{$admin=User::factory()->create(['role'=>'admin']);$permission=Permission::create(['name'=>'leads.view','display_name'=>'View leads','resource'=>'leads','action'=>'view']);$this->actingAs($admin);Livewire::test(Groups::class)->set('name','lead_readers')->set('display_name','Lead readers')->set('permission_ids',[$permission->id])->call('save')->assertHasNoErrors();$group=PermissionGroup::where('name','lead_readers')->firstOrFail();$this->assertTrue($group->permissions()->whereKey($permission->id)->exists());}
}
